        UString to_ustring(const rust::String &text) {
            const std::string_view view{text.data(), text.size()};
            if (auto converted = UString::try_from_utf8(view)) {
                return std::move(*converted);
            }
            return UString{};
        }

        rust::String to_rust_string(const UString &text) {
            return rust::String::lossy(text.data(), text.size());
        }

        rust::String to_rust_string(const std::string &text) {
            return rust::String::lossy(text);
        }

        // Additional windows opened through `window_open`/`window_recreate` are owned here (mirroring
        // `Application::windows_`'s ownership of every window it spawns) since `Engine::add_window`
        // only borrows the `WindowManager::Window` it is given; something has to keep it alive for as
        // long as the surface it backs is registered.
        std::unordered_map<std::uint64_t, std::unique_ptr<W::Window>> g_windows;

        C::RenderSurfaceHandle to_surface(SurfaceHandle handle) noexcept {
            return C::RenderSurfaceHandle{static_cast<W::WindowId>(handle.window_id)};
        }

