            out.cascade_count = s.cascade_count;
            out.max_distance = s.max_distance;
            out.cascade_split_lambda = s.cascade_split_lambda;
            out.cascade_blend = s.cascade_blend;
            out.depth_bias = s.depth_bias;
            out.slope_bias = s.slope_bias;
            for (std::size_t i = 0; i < out.cascade_resolutions.size(); ++i) {
                out.cascade_resolutions[i] = s.cascade_resolutions[i];
            }
            out.filter_radius_texels = s.filter_radius_texels;
            out.normal_bias = s.normal_bias;
            out.debug_view = map(s.debug_view);
            out.max_shadowed_spot_lights = s.max_shadowed_spot_lights;
            out.max_shadowed_point_lights = s.max_shadowed_point_lights;
            out.contact_hardening = s.contact_hardening;
