    SFT::Engine::RenderGraph render_graph_from_settings(const RenderGraphSettings &settings) noexcept {
        // `to_engine` is declared inside the anonymous namespace just above; still reachable
        // unqualified here since anonymous-namespace members are visible for the rest of the file.
        return SFT::Engine::RenderGraph{to_engine(settings)};
    }

    namespace {
        std::mutex g_pending_render_graph_mutex;
        std::optional<SFT::Engine::RenderGraph> g_pending_render_graph;
    } // namespace

    void set_pending_render_graph(const RenderGraphSettings &settings) {
        const std::lock_guard<std::mutex> lock{g_pending_render_graph_mutex};
        g_pending_render_graph = render_graph_from_settings(settings);
    }

    SFT::Engine::RenderGraph consume_pending_render_graph() noexcept {
        const std::lock_guard<std::mutex> lock{g_pending_render_graph_mutex};
        return g_pending_render_graph.value_or(SFT::Engine::RenderGraph::empty());
    }

    namespace {

        W::WindowConfig build_window_config(const WindowDesc &desc, const std::string &title) noexcept {
            W::WindowConfig config{};
            config.title = title.c_str();
            config.extent = {desc.width, desc.height};
            config.position = {desc.x, desc.y};
            config.use_default_position = desc.use_default_position;
            config.visible = desc.visible;
            config.resizable = desc.resizable;
            config.decorated = desc.decorated;
            config.high_dpi = desc.high_dpi;
            config.transparent = desc.transparent;
            config.mode = map(desc.window_mode);
            config.graphics_api = W::WindowGraphicsApi::Vulkan;
            return config;
        }

        WindowOpenResult open_window_impl(EngineView &engine, const WindowDesc &desc) {
            const std::string title{desc.title};
            const W::WindowConfig config = build_window_config(desc, title);

            auto created = W::Window::create<W::SDL3::SDL3Window>(config);
            if (!created) {
                return WindowOpenResult{false, to_rust_string(created.error().message), SurfaceHandle{UINT64_MAX}};
            }
            std::unique_ptr<W::Window> window = std::move(*created);
            const auto window_id = static_cast<std::uint64_t>(window->id());

            auto added = engine.add_window(*window, desc.desired_frames_in_flight);
            if (!added) {
                return WindowOpenResult{false, to_rust_string(added.error().message), SurfaceHandle{UINT64_MAX}};
            }

            g_windows.emplace(window_id, std::move(window));
            return WindowOpenResult{true, rust::String(), SurfaceHandle{window_id}};
        }

    } // namespace

    WindowOpenResult window_open(EngineView &engine, const WindowDesc &desc) {
        return open_window_impl(engine, desc);
    }

    WindowOpenResult window_recreate(EngineView &engine, SurfaceHandle old_surface, const WindowDesc &desc) {
        const std::string title{desc.title};
        const W::WindowConfig config = build_window_config(desc, title);

        const auto old_it = g_windows.find(old_surface.window_id);
        if (old_it == g_windows.end()) {
            return WindowOpenResult{false, rust::String("unknown surface"), SurfaceHandle{UINT64_MAX}};
        }

        auto created = W::Window::create<W::SDL3::SDL3Window>(config);
        if (!created) {
            return WindowOpenResult{false, to_rust_string(created.error().message), SurfaceHandle{UINT64_MAX}};
        }
        std::unique_ptr<W::Window> window = std::move(*created);
        const auto new_window_id = static_cast<std::uint64_t>(window->id());

        auto recreated = engine.recreate_window(to_surface(old_surface), *window, desc.desired_frames_in_flight);
        if (!recreated) {
            return WindowOpenResult{false, to_rust_string(recreated.error().message), SurfaceHandle{UINT64_MAX}};
        }

        g_windows.erase(old_it);
        g_windows.emplace(new_window_id, std::move(window));
        return WindowOpenResult{true, rust::String(), SurfaceHandle{new_window_id}};
    }

    void window_close(EngineView &engine, SurfaceHandle surface) noexcept {
        engine.remove_window(to_surface(surface));
        g_windows.erase(surface.window_id);
    }

    void window_notify_resize(EngineView &engine, SurfaceHandle surface, std::uint32_t width, std::uint32_t height) noexcept {
        engine.on_surface_resize_needed(to_surface(surface), C::Extent2D{width, height});
    }

