    OffscreenTargetCreateResult offscreen_target_create(EngineView &engine, const OffscreenTargetDesc &desc) {
        E::OffscreenRenderTargetDescription description{};
        description.width = desc.width;
        description.height = desc.height;
        description.label = to_ustring(desc.label);

        auto created = engine.create_offscreen_render_target(description);
        if (!created) {
            return OffscreenTargetCreateResult{false, to_rust_string(created.error().message), 0};
        }
        return OffscreenTargetCreateResult{true, rust::String(), created->value};
    }

    void offscreen_target_destroy(EngineView &engine, std::uint64_t handle) noexcept {
        engine.destroy_offscreen_render_target(E::RenderTargetHandle{handle});
    }

    bool offscreen_target_description(const EngineView &engine, std::uint64_t handle, OffscreenTargetDesc &out) {
        const auto description = engine.offscreen_render_target_description(E::RenderTargetHandle{handle});
        if (!description) {
            return false;
        }
        out.width = description->width;
        out.height = description->height;
        out.label = to_rust_string(description->label);
        return true;
    }

    std::uint64_t offscreen_target_texture(const EngineView &engine, std::uint64_t handle) noexcept {
        return engine.offscreen_render_target_texture(E::RenderTargetHandle{handle}).value;
    }

    PresentationSettings presentation_settings_get(const EngineView &engine, SurfaceHandle surface) noexcept {
        const C::PresentationSettings settings = engine.presentation_settings(to_surface(surface));
        PresentationSettings out{};
        out.vsync = [&] {
            switch (settings.vsync) {
            case C::VSyncMode::Off: return VSync::Off;
            case C::VSyncMode::On: return VSync::On;
            case C::VSyncMode::Adaptive: return VSync::Adaptive;
            }
            return VSync::On;
        }();
        out.variable_refresh = [&] {
            switch (settings.variable_refresh) {
            case C::VariableRefreshMode::Disabled: return VariableRefresh::Disabled;
            case C::VariableRefreshMode::Automatic: return VariableRefresh::Automatic;
            case C::VariableRefreshMode::Preferred: return VariableRefresh::Preferred;
            }
            return VariableRefresh::Automatic;
        }();
        out.latency = [&] {
            switch (settings.latency) {
            case C::LatencyMode::Normal: return LatencyMode::Normal;
            case C::LatencyMode::Low: return LatencyMode::Low;
            case C::LatencyMode::Ultra: return LatencyMode::Ultra;
            }
            return LatencyMode::Normal;
        }();
        out.preference = [&] {
            switch (settings.preference) {
            case C::PresentationPreference::Automatic: return PresentationPreference::Automatic;
            case C::PresentationPreference::LowestLatency: return PresentationPreference::LowestLatency;
            case C::PresentationPreference::Smoothest: return PresentationPreference::Smoothest;
            case C::PresentationPreference::PowerEfficient: return PresentationPreference::PowerEfficient;
            }
            return PresentationPreference::Automatic;
        }();
        out.hdr_enabled = static_cast<bool>(settings.hdr_enabled);
        out.hdr_color_space = map(settings.hdr_color_space);
        out.transparent_composition = static_cast<bool>(settings.transparent_composition);
        out.swapchain_image_count = settings.swapchain_image_count;
        out.allow_present_from_compute = static_cast<bool>(settings.allow_present_from_compute);
        return out;
    }

    Status presentation_settings_set(EngineView &engine, SurfaceHandle surface, const PresentationSettings &settings) {
        C::PresentationSettings native{};
        native.vsync = map(settings.vsync);
        native.variable_refresh = map(settings.variable_refresh);
        native.latency = map(settings.latency);
        native.preference = map(settings.preference);
        native.hdr_enabled = settings.hdr_enabled;
        native.hdr_color_space = map(settings.hdr_color_space);
        native.transparent_composition = settings.transparent_composition;
        native.swapchain_image_count = settings.swapchain_image_count;
        native.allow_present_from_compute = settings.allow_present_from_compute;

        const C::RendererResult result = engine.set_presentation_settings(to_surface(surface), native);
        if (!result) {
            return Status{false, to_rust_string(result.error().message)};
        }
        return Status{true, rust::String()};
    }

    PresentationResolution presentation_resolution_query(const EngineView &engine, SurfaceHandle surface) noexcept {
        const R::PresentationResolution resolution = engine.presentation_resolution(to_surface(surface));
        PresentationResolution out{};
        out.strategy = rust::String(std::string{R::present_strategy_name(resolution.strategy)});
        out.effective_mode = rust::String(std::string{R::present_mode_name(resolution.effective_mode)});
        out.degraded = resolution.degraded;
        out.present_queue_is_compute = resolution.present_queue_is_compute;
        out.effective_composite_alpha = rust::String(std::string{R::composite_alpha_mode_name(resolution.effective_composite_alpha)});
        out.composite_alpha_degraded = resolution.composite_alpha_degraded;
        out.via_composition_present = resolution.via_composition_present;
        out.supports_completion_fence = resolution.supports_completion_fence;
        out.full_screen_exclusive_active = resolution.full_screen_exclusive_active;
        out.effective_format = static_cast<std::uint32_t>(resolution.effective_format);
        out.effective_color_space = static_cast<std::uint32_t>(resolution.effective_color_space);
        return out;
    }

    HdrCapabilityQuery hdr_capabilities_query(const EngineView &engine, SurfaceHandle surface) {
        const auto queried = engine.query_hdr_capabilities(to_surface(surface));
        HdrCapabilityQuery out{};
        if (!queried) {
            out.ok = false;
            out.message = to_rust_string(queried.error().message);
            return out;
        }
        const R::SurfaceHdrCapabilityQuery &query = *queried;
        out.ok = static_cast<bool>(query);
        out.message = to_rust_string(query.message.message);
        out.hdr_supported = query.capabilities.hdr_supported;
        out.hdr_enabled_by_os = query.capabilities.hdr_enabled_by_os;
        out.hdr_metadata_output_supported = query.capabilities.hdr_metadata_output_supported;
        for (const R::HdrPresentationMode &mode : query.capabilities.supported_modes) {
            out.supported_modes.push_back(HdrPresentationMode{map(mode.transfer), map(mode.gamut), mode.requires_os_hdr_mode});
        }
        out.has_display_metadata = query.capabilities.display_metadata.has_value();
        if (out.has_display_metadata) {
            const R::HdrDisplayMetadata &metadata = *query.capabilities.display_metadata;
            out.display_metadata.red_primary_x = metadata.red_primary.x;
            out.display_metadata.red_primary_y = metadata.red_primary.y;
            out.display_metadata.green_primary_x = metadata.green_primary.x;
            out.display_metadata.green_primary_y = metadata.green_primary.y;
            out.display_metadata.blue_primary_x = metadata.blue_primary.x;
            out.display_metadata.blue_primary_y = metadata.blue_primary.y;
            out.display_metadata.white_point_x = metadata.white_point.x;
            out.display_metadata.white_point_y = metadata.white_point.y;
            out.display_metadata.min_luminance_nits = metadata.min_luminance_nits;
            out.display_metadata.max_luminance_nits = metadata.max_luminance_nits;
            out.display_metadata.max_full_frame_luminance_nits = metadata.max_full_frame_luminance_nits;
        }
        out.sdr_white_nits = query.capabilities.sdr_white_nits;
        out.edr_headroom = query.capabilities.edr_headroom;
        out.max_edr_headroom = query.capabilities.max_edr_headroom;
        return out;
    }

    Status hdr_update_content_light_level(EngineView &engine, SurfaceHandle surface, const HdrContentLightLevelUpdate &update) {
        R::HdrContentLightLevelUpdate native{};
        native.max_content_light_level_nits = update.max_content_light_level_nits;
        native.max_frame_average_light_level_nits = update.max_frame_average_light_level_nits;

        const R::RhiResult result = engine.update_hdr_content_light_level(to_surface(surface), native);
        if (!result) {
            return Status{false, to_rust_string(result.error().message)};
        }
        return Status{true, rust::String()};
    }

    Status render_graph_settings_validate(const RenderGraphSettings &settings) {
        E::RenderGraph graph(to_engine(settings));
        const E::RenderGraphResult result = graph.validate();
        if (!result) {
            return Status{false, to_rust_string(result.error().message)};
        }
        return Status{true, rust::String()};
    }

